arguments.command:
cd /workspace && python3 -c "
import sys; sys.path.insert(0,'dev')
import ref, json
cases=json.load(open('examples.json'))
for c in cases:
    out=[ref.run(x) for x in c['input']['cases']]
    exp=c['output']['cases']
    for got,want in zip(out,exp):
        for k in want:
            if got.get(k)!=want[k]:
                print(c['name'],'KEY',k)
                print(' got ',json.dumps(got.get(k))[:600])
                print(' want',json.dumps(want[k])[:600])
        extra=set(got)-set(want)
        if extra: print('extra keys',extra)
"
